SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind AS max_phase_for_ind FROM drug_indication di JOIN molecule_dictionary md ON md.molregno = di.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE (di.mesh_heading = 'HIV Infection' OR di.efo_term = 'HIV infection') AND md.max_phase = 4 ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id, di.efo_term, di.max_phase_for_ind
